import os
from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch.actions import IncludeLaunchDescription, SetEnvironmentVariable
from launch.launch_description_sources import PythonLaunchDescriptionSource
from launch_ros.actions import Node

# Same 3-marker test as aruco.launch.py, but on uneven terrain (worlds/terrain_world.sdf,
# generated by scripts/generate_terrain_world.py). Also adds a ZED depth point cloud on
# /zed/depth/points for the traversability work.

# Depth sensor added to the rover at launch time so rover_sim.urdf stays untouched.
# gz depth-camera point clouds use the link convention (x forward, z up), not the optical
# frame, so the points are stamped with zed_camera_link.
ZED_DEPTH_SENSOR = """
  <gazebo reference="zed_camera_link">
    <sensor name="zed_depth_camera" type="depth_camera">
      <always_on>true</always_on>
      <update_rate>10</update_rate>
      <visualize>false</visualize>
      <topic>/zed/depth</topic>
      <gz_frame_id>zed_camera_link</gz_frame_id>
      <camera>
        <horizontal_fov>1.919862</horizontal_fov>
        <image>
          <width>640</width>
          <height>360</height>
          <format>R_FLOAT32</format>
        </image>
        <clip>
          <near>0.3</near>
          <far>15</far>
        </clip>
        <noise>
          <type>gaussian</type>
          <mean>0.0</mean>
          <stddev>0.01</stddev>
        </noise>
      </camera>
    </sensor>
  </gazebo>
"""

# DiffDrive's wheel odometry assumes the wheels never slip, which a skid-steer rover does
# constantly when turning: one 8 s in-place turn left /odom ~80 deg off the true heading.
# On terrain, /odom and odom->chassis_footprint come from the true 3D pose instead (a
# stand-in for the ZED's visual-inertial tracking on the real rover); DiffDrive's own
# odometry is moved to /odom_wheel and /tf_wheel so it doesn't fight it.
GROUND_TRUTH_ODOM = """
  <gazebo>
    <plugin filename="gz-sim-odometry-publisher-system" name="gz::sim::systems::OdometryPublisher">
      <odom_frame>odom</odom_frame>
      <robot_base_frame>chassis_footprint</robot_base_frame>
      <odom_topic>odom</odom_topic>
      <tf_topic>tf</tf_topic>
      <odom_publish_frequency>30</odom_publish_frequency>
      <dimensions>3</dimensions>
    </plugin>
  </gazebo>
"""


def generate_launch_description():
    pkg_rover_description = get_package_share_directory('rover_description')
    pkg_ros_gz_sim = get_package_share_directory('ros_gz_sim')

    rviz_config_file = os.path.join(pkg_rover_description, 'config', 'rover.rviz')
    urdf_path = os.path.join(pkg_rover_description, 'urdf', 'rover_sim.urdf')
    world_path = os.path.join(pkg_rover_description, 'worlds', 'terrain_world.sdf')
    models_path = os.path.join(pkg_rover_description, 'models')
    worlds_dir = os.path.join(pkg_rover_description, 'worlds')

    with open(urdf_path, 'r') as infp:
        robot_desc = infp.read()
    robot_desc = robot_desc.replace('<odom_topic>odom</odom_topic>', '<odom_topic>odom_wheel</odom_topic>')
    robot_desc = robot_desc.replace('<tf_topic>tf</tf_topic>', '<tf_topic>tf_wheel</tf_topic>')
    robot_desc = robot_desc.replace('</robot>', ZED_DEPTH_SENSOR + GROUND_TRUTH_ODOM + '</robot>')

    # Points Gazebo to install share directory, models, and worlds so URIs resolve properly
    install_share_dir = os.path.dirname(pkg_rover_description)
    gz_resource_path = f"{install_share_dir}:{models_path}:{worlds_dir}"
    for i in range(18):
        gz_resource_path += f":{models_path}/marker_{i}/materials/textures:{models_path}/marker{i}/materials/textures"

    set_gz_resource_path = SetEnvironmentVariable(
        name='GZ_SIM_RESOURCE_PATH',
        value=gz_resource_path
    )

    # 1. Gazebo Harmonic with the terrain world
    gz_sim = IncludeLaunchDescription(
        PythonLaunchDescriptionSource(
            os.path.join(pkg_ros_gz_sim, 'launch', 'gz_sim.launch.py')
        ),
        launch_arguments={'gz_args': f'-r {world_path}'}.items()
    )

    # 2. Robot State and TFs
    robot_state_publisher = Node(
        package='robot_state_publisher',
        executable='robot_state_publisher',
        name='robot_state_publisher',
        output='both',
        parameters=[{
            'robot_description': robot_desc,
            'use_sim_time': True
        }]
    )

    # 3. Static Transform Publisher for ZED Optical Frame
    zed_optical_tf = Node(
        package='tf2_ros',
        executable='static_transform_publisher',
        name='zed_optical_frame_publisher',
        output='screen',
        arguments=[
            '--x', '0', '--y', '0', '--z', '0',
            '--roll', '-1.57079632679', '--pitch', '0', '--yaw', '-1.57079632679',
            '--frame-id', 'zed_camera_link',
            '--child-frame-id', 'zed_camera_optical_frame'
        ],
        parameters=[{'use_sim_time': True}]
    )

    # 4. Spawn the rover at the start pad (terrain at the origin is ~0.01 m)
    spawn_rover = Node(
        package='ros_gz_sim',
        executable='create',
        arguments=[
            '-topic', 'robot_description',
            '-name', 'rover',
            '-z', '0.5'
        ],
        output='screen'
    )

    # 5. ROS-Gazebo Bridge
    ros_gz_bridge = Node(
        package='ros_gz_bridge',
        executable='parameter_bridge',
        arguments=[
            # Simulation & Core Robotics
            '/clock@rosgraph_msgs/msg/Clock[gz.msgs.Clock',
            '/cmd_vel@geometry_msgs/msg/Twist]gz.msgs.Twist',
            '/odom@nav_msgs/msg/Odometry[gz.msgs.Odometry',
            '/tf@tf2_msgs/msg/TFMessage[gz.msgs.Pose_V',
            '/tf_static@tf2_msgs/msg/TFMessage[gz.msgs.Pose_V',
            '/joint_states@sensor_msgs/msg/JointState[gz.msgs.Model',

            # ZED RGB Camera Feed & Calibration Info
            '/zed/image_raw@sensor_msgs/msg/Image[gz.msgs.Image',
            '/zed/camera_info@sensor_msgs/msg/CameraInfo[gz.msgs.CameraInfo',

            # ZED Depth Point Cloud
            '/zed/depth/points@sensor_msgs/msg/PointCloud2[gz.msgs.PointCloudPacked',

            # ZED IMU Sensor Data
            '/zed/imu/data@sensor_msgs/msg/Imu[gz.msgs.IMU',
        ],
        output='screen'
    )

    # 6. RViz2 for visualization
    rviz = Node(
        package='rviz2',
        executable='rviz2',
        name='rviz2',
        output='screen',
        arguments=['-d', rviz_config_file],
        parameters=[{'use_sim_time': True}]
    )

    sim_time_param = {'use_sim_time': True}

    # 7. ArUco Detector Node
    aruco_detector_node = Node(
        package='rover_aruco',
        executable='aruco_detector',
        name='aruco_detector',
        output='screen',
        parameters=[
            sim_time_param,
            {
                'image_topic': '/zed/image_raw',
                'camera_info_topic': '/zed/camera_info',
                'output_topic': '/aruco/markers',
                'marker_size_meters': 0.175,
                'enable_debug_window': True
            }
        ]
    )

    # 8. Goal Generator Node (marker x/y are the same as aruco_world.sdf)
    goal_generator_node = Node(
        package='rover_aruco',
        executable='goal_generator',
        name='goal_generator',
        output='screen',
        parameters=[sim_time_param]
    )

    # 9. Marker Tracker Node
    marker_tracker_node = Node(
        package='rover_aruco',
        executable='marker_tracker',
        name='marker_tracker',
        output='screen',
        parameters=[sim_time_param]
    )

    # 10. Obstacle Avoidance / Rover Movement Node
    # Speeds capped well below movement.py's flat-ground defaults (2.4 m/s, 6 rad/s):
    # spinning that hard among the rocks rolled the rover over in testing.
    obs_avoid_node = Node(
        package='rover_aruco',
        executable='obs_avoid',
        name='obs_avoid',
        output='screen',
        parameters=[
            sim_time_param,
            {
                'cmd_vel_topic': '/cmd_vel',
                'odom_topic': '/odom',
                'scan_topic': '/scan',
                'max_linear_speed': 0.8,
                'max_angular_speed': 1.0
            }
        ]
    )

    return LaunchDescription([
        set_gz_resource_path,
        gz_sim,
        robot_state_publisher,
        zed_optical_tf,
        spawn_rover,
        ros_gz_bridge,
        rviz,
        aruco_detector_node,
        goal_generator_node,
        marker_tracker_node,
        obs_avoid_node
    ])
